/* ---- derive-1.js ---- */
/* Twistor: rewritten by the build without the university topics. */
window.WL = window.WL || {};
(function (WL) {
Object.assign((WL.derive = WL.derive || {}), {"ks3-energy":{"steps":[{"say":"Energy is never made or destroyed, so everything put in must come out somewhere.","tex":"E_{\\text{in}} = E_{\\text{useful}} + E_{\\text{wasted}}","why":"This is conservation of energy, the best-tested rule in physics. If the two sides ever differed, energy would have appeared from nothing or vanished."},{"say":"Efficiency is the fraction of the input that ends up where we want it.","tex":"\\text{efficiency} = \\frac{E_{\\text{useful}}}{E_{\\text{in}}}","why":"It is a definition: a fraction compares a part with the whole. Multiply by 100 to get a percentage."},{"say":"Replace the useful energy using the first line.","tex":"\\text{efficiency} = \\frac{E_{\\text{in}} - E_{\\text{wasted}}}{E_{\\text{in}}} = 1 - \\frac{E_{\\text{wasted}}}{E_{\\text{in}}}","why":"Useful = in − wasted, so the efficiency falls short of 1 by exactly the wasted fraction."},{"say":"Wasted energy cannot be negative, so the efficiency can never pass 1.","tex":"E_{\\text{wasted}} \\ge 0 \\;\\Longrightarrow\\; \\text{efficiency} \\le 1","why":"A machine giving out more than it takes in would be creating energy. In practice some energy always heats the surroundings, so real efficiencies are below 100%."}],"result":"\\text{efficiency} = \\frac{E_{\\text{useful}}}{E_{\\text{in}}} = 1 - \\frac{E_{\\text{wasted}}}{E_{\\text{in}}} \\le 1","assume":["“Wasted” depends on what you want: the heat from a lamp is wasted, the heat from a heater is useful.","Heat pumps deliver more heat than the electrical energy they use, but they move energy from outside; counting that input, conservation still holds."]},"ks3-forces":{"steps":[{"say":"Experiments show that the pull of gravity on an object doubles when its mass doubles.","tex":"W \\propto m","why":"Hang 100 g, 200 g, 300 g on a newton-meter and the readings are 1 N, 2 N, 3 N: a straight line through the origin."},{"say":"A proportionality becomes an equation with a constant, called g.","tex":"W = m g, \\qquad g \\approx 10\\ \\text{N/kg on Earth}","why":"g is the gradient of the weight–mass graph: the newtons of pull on each kilogram."},{"say":"Forces along one line combine: those in the same direction add, opposite ones subtract.","tex":"F_{\\text{resultant}} = F_{\\text{forward}} - F_{\\text{backward}}","why":"A force has a direction. Choosing forward as positive, backward forces count as negative."},{"say":"A falling object speeds up until air resistance has grown to equal its weight.","tex":"F_{\\text{resultant}} = W - F_{\\text{air}} = 0 \\;\\Longrightarrow\\; \\text{steady speed}","why":"Air resistance increases with speed. When the resultant reaches zero the speed stops changing: terminal velocity."}],"result":"W = mg, \\qquad F_{\\text{resultant}} = 0 \\Leftrightarrow \\text{no change in speed}","assume":["g is 10 N/kg only near Earth’s surface (more precisely 9.8); on the Moon it is 1.6 N/kg.","In a vacuum there is no air resistance, so a feather and a hammer fall together, as shown on the Moon by Apollo 15."]},"ks3-density":{"steps":[{"say":"Density says how much mass is packed into each unit of volume.","tex":"\\rho = \\frac{m}{V}","why":"A definition. Two blocks of the same size can have different masses; dividing by volume makes a fair comparison."},{"say":"An object placed in water pushes aside its own volume of water, which lets us measure an awkward shape.","tex":"V = V_{\\text{after}} - V_{\\text{before}}","why":"Water cannot be squashed, so the level rises by exactly the volume that went in."},{"say":"A fully submerged object is pushed up by a force equal to the weight of the water it pushed aside.","tex":"F_{\\text{up}} = \\rho_{\\text{water}} V g, \\qquad W = \\rho_{\\text{object}} V g","why":"This is Archimedes’ principle. Both forces contain the same volume V and the same g."},{"say":"Compare the two: the object sinks if its weight is larger.","tex":"W > F_{\\text{up}} \\iff \\rho_{\\text{object}} > \\rho_{\\text{water}}","why":"V and g cancel from both sides, so only the densities matter, not the size of the object."}],"result":"\\rho = \\frac{m}{V}; \\quad \\text{floats if } \\rho_{\\text{object}} < \\rho_{\\text{liquid}}","assume":["A steel ship floats because its average density, including the air inside the hull, is below that of water.","Density changes with temperature: most things expand when heated, so their density falls."]},"ks3-heat":{"steps":[{"say":"Temperature measures how fast particles jiggle on average; heat is energy moving because of a temperature difference.","tex":"\\text{heat flows: hot} \\rightarrow \\text{cold}","why":"Faster particles hand energy to slower ones in collisions far more often than the reverse."},{"say":"Mix two amounts of the same liquid. Energy lost by the hot part equals energy gained by the cold part.","tex":"m_1 c\\,(T_1 - T) = m_2 c\\,(T - T_2)","why":"Conservation of energy, with no losses to the room. Each kilogram stores c joules per degree, so energy change = mass × c × temperature change."},{"say":"The same liquid means c cancels. Expand the brackets and collect T.","tex":"m_1T_1 + m_2T_2 = (m_1 + m_2)\\,T","why":"Move every term with the unknown T to one side."},{"say":"Divide to find the final temperature.","tex":"T = \\frac{m_1T_1 + m_2T_2}{m_1 + m_2}","why":"It is a weighted average: the larger mass pulls the answer towards its own temperature."}],"result":"T_{\\text{mix}} = \\frac{m_1T_1 + m_2T_2}{m_1 + m_2}","assume":["Only for the same substance, with no change of state and no energy lost to the container or the air.","A bath at 40 °C holds far more thermal energy than a spark at 1000 °C: temperature is not the same as energy."]},"ks3-climate":{"steps":[{"say":"Carbon dioxide is measured in parts per million. Convert to a percentage.","tex":"420\\ \\text{ppm} = \\frac{420}{1\\,000\\,000} = 0.042\\%","why":"1% is one part in a hundred, which is 10 000 parts in a million. So divide ppm by 10 000."},{"say":"Earth’s temperature is steady when energy arriving equals energy leaving.","tex":"P_{\\text{in (sunlight)}} = P_{\\text{out (infrared)}}","why":"If more arrived than left, energy would pile up and the planet would warm until the two balanced again."},{"say":"Greenhouse gases absorb some outgoing infrared and send part of it back down.","tex":"P_{\\text{out}} < P_{\\text{in}} \\;\\Longrightarrow\\; \\text{energy accumulates}","why":"CO₂ and water vapour are transparent to sunlight but absorb infrared, so they cut the outgoing flow without changing the incoming one."},{"say":"The surface warms until it radiates enough to restore the balance at a higher temperature.","tex":"T \\uparrow \\;\\Longrightarrow\\; P_{\\text{out}} \\uparrow \\;\\text{until}\\; P_{\\text{out}} = P_{\\text{in}}","why":"Hotter objects radiate more. The new balance point is warmer than the old one."}],"result":"\\text{more CO}_2 \\Rightarrow P_{\\text{out}} \\text{ drops} \\Rightarrow T \\text{ rises until } P_{\\text{in}} = P_{\\text{out}}","assume":["Without any greenhouse effect Earth would average about −18 °C; the natural effect is what keeps it near +15 °C.","How much warming follows a given CO₂ rise also depends on feedbacks (ice, clouds, water vapour), which is where the scientific uncertainty lies."]},"ks3-sound":{"steps":[{"say":"Sound travels at a steady speed, so the usual speed equation applies.","tex":"v = \\frac{\\text{distance}}{\\text{time}}","why":"Sound in air at room temperature covers about 340 m every second."},{"say":"An echo has gone to the wall and come back: twice the distance d to the wall.","tex":"v = \\frac{2d}{t}","why":"The timer runs for the whole round trip, there and back."},{"say":"Rearrange for the distance to the wall.","tex":"d = \\frac{v\\,t}{2}","why":"Multiply both sides by t and divide by 2. Forgetting the 2 is the classic mistake."},{"say":"Pitch is set by how many vibrations happen each second: one divided by the time for one vibration.","tex":"f = \\frac{1}{T}","why":"If one vibration takes 0.01 s, then 100 fit into a second, so f = 100 Hz."}],"result":"d = \\frac{vt}{2}, \\qquad f = \\frac{1}{T}","assume":["The speed of sound changes with temperature and with the material: about 340 m/s in air, 1500 m/s in water, 5000 m/s in steel.","Sound needs particles to pass the vibration on, so there is no sound in a vacuum."]},"ks3-colour":{"steps":[{"say":"White light is a mixture of colours. Each colour slows by a different amount in glass.","tex":"v_{\\text{violet in glass}} < v_{\\text{red in glass}}","why":"Measured fact: glass slows violet light slightly more than red."},{"say":"The more a colour slows, the more its ray bends on entering the glass.","tex":"\\text{bending: violet} > \\text{blue} > \\text{green} > \\text{yellow} > \\text{red}","why":"Refraction is caused by the change of speed. A bigger change gives a bigger turn."},{"say":"A prism bends twice in the same direction, spreading the colours into a spectrum.","tex":"\\text{white} \\rightarrow \\text{R, O, Y, G, B, I, V}","why":"The angled faces mean the second refraction adds to the first instead of undoing it, as it would in a parallel-sided block."},{"say":"An object’s colour is the light it reflects; a filter’s colour is the light it lets through.","tex":"\\text{red object in green light}: \\text{reflects nothing} \\Rightarrow \\text{looks black}","why":"A red surface absorbs every colour except red. With no red light arriving, nothing comes back to your eye."}],"result":"\\text{R} + \\text{G} + \\text{B} = \\text{white (light)}; \\quad \\text{surface colour} = \\text{light reflected}","assume":["Mixing paints is different from mixing light: each pigment removes colours, so mixing all paints tends to black.","“Seven colours” is a convention; the spectrum is continuous."]},"ks3-parallel":{"steps":[{"say":"Charge is not used up, so the current arriving at a junction equals the current leaving.","tex":"I_{\\text{supply}} = I_1 + I_2","why":"Electrons cannot pile up at a junction or vanish; what flows in must flow out."},{"say":"Each branch is connected straight across the supply, so each gets the full voltage.","tex":"V_1 = V_2 = V_{\\text{supply}}","why":"Both ends of every branch join the same two wires, so the push across each branch is the same."},{"say":"Resistance is defined as the voltage needed per amp of current.","tex":"R = \\frac{V}{I}","why":"A component that needs a big push for a small current has a high resistance."},{"say":"Adding a branch adds current at the same voltage, so the whole circuit’s resistance falls.","tex":"R_{\\text{total}} = \\frac{V}{I_1 + I_2} < \\frac{V}{I_1}","why":"A bigger number on the bottom of a fraction makes the fraction smaller: more paths, less resistance."}],"result":"I_{\\text{supply}} = I_1 + I_2, \\quad V_1 = V_2, \\quad R = \\frac{V}{I}","assume":["Real cells have some internal resistance, so the voltage drops a little when many branches draw a large current.","In series the rules swap: the current is the same everywhere and the voltages add."]},"ks3-magnets":{"steps":[{"say":"A wire carrying a current has a magnetic field around it.","tex":"\\text{current} \\Rightarrow \\text{magnetic field}","why":"Oersted saw a compass needle swing when a nearby current was switched on (1820)."},{"say":"Coiling the wire makes the fields of all the turns add up along the axis.","tex":"B \\propto N \\ (\\text{turns})","why":"Each turn makes the same field in the same direction inside the coil, so N turns give N times the field."},{"say":"The field of each turn grows in proportion to the current.","tex":"B \\propto I","why":"Double the flow of charge and the magnetic effect of each turn doubles."},{"say":"An iron core becomes magnetised itself and adds its own, much larger, field.","tex":"B_{\\text{with iron}} \\gg B_{\\text{air core}}","why":"Iron contains tiny magnetic regions that line up with the coil’s field. Soft iron loses this again when the current stops, which is what makes the magnet switchable."}],"result":"\\text{strength} \\uparrow \\text{ with turns } N,\\ \\text{current } I,\\ \\text{and an iron core}","assume":["The iron saturates: beyond a certain current nearly all its regions are aligned and extra current adds little.","Steel would stay magnetised after switching off, so it is the wrong core for an electromagnet."]},"ks3-tides-eclipses":{"steps":[{"say":"Gravity weakens with distance, so the Moon pulls the near side of Earth harder than the far side.","tex":"F_{\\text{near}} > F_{\\text{centre}} > F_{\\text{far}}","why":"The near-side ocean is about 6400 km closer to the Moon than Earth’s centre, the far side 6400 km further."},{"say":"Relative to Earth’s centre, water is stretched towards the Moon on one side and left behind on the other.","tex":"\\text{two bulges: one facing the Moon, one opposite}","why":"What matters is the difference in pull. The near side is pulled more than the centre; the centre is pulled more than the far side."},{"say":"Earth spins under the two bulges once a day, so most coasts see two high tides.","tex":"\\text{interval} \\approx \\tfrac12 \\times 24\\ \\text{h}\\ 50\\ \\text{min} = 12\\ \\text{h}\\ 25\\ \\text{min}","why":"The extra 50 minutes is because the Moon has moved on in its orbit while Earth turned."},{"say":"An eclipse needs Sun, Earth and Moon in a straight line.","tex":"\\text{solar: Moon between (new Moon)}; \\quad \\text{lunar: Earth between (full Moon)}","why":"A shadow only falls on something directly behind the object that blocks the light."}],"result":"\\text{two tidal bulges} \\Rightarrow \\text{high tide every} \\approx 12\\ \\text{h}\\ 25\\ \\text{min}","assume":["The Moon’s orbit is tilted by about 5°, so the line-up usually misses and there is no eclipse every month.","Real tides are shaped by coastlines and ocean depth; the Sun adds about half the Moon’s effect (spring and neap tides)."]},"ks3-solar-system":{"steps":[{"say":"Light travels at a fixed speed, so a time of travel measures a distance.","tex":"d = c\\,t, \\qquad c = 300\\,000\\ \\text{km/s}","why":"The ordinary distance = speed × time, with the speed of light."},{"say":"Count the seconds in one year.","tex":"t = 365 \\times 24 \\times 3600\\ \\text{s} \\approx 3.15 \\times 10^{7}\\ \\text{s}","why":"Days × hours in a day × seconds in an hour."},{"say":"Multiply to get the distance light covers in a year.","tex":"1\\ \\text{light-year} = 300\\,000 \\times 3.15\\times10^{7} \\approx 9.5 \\times 10^{12}\\ \\text{km}","why":"A light-year is a distance, not a time."},{"say":"Looking far away is looking back in time.","tex":"t = \\frac{d}{c}: \\quad \\text{Sun } 8\\ \\text{min}, \\quad \\text{nearest star } 4.2\\ \\text{years}","why":"The light you see left its source that long ago."}],"result":"1\\ \\text{light-year} \\approx 9.5\\times10^{12}\\ \\text{km}","assume":["The speed of light quoted is for a vacuum; space is close enough to one.","Planet formation, the giant-impact origin of the Moon and similar stories are models supported by evidence (rock ages, compositions, simulations), not direct observations."]},"ks3-earth":{"steps":[{"say":"Plates move at a steady, tiny speed, so distance = speed × time still works.","tex":"d = v\\,t","why":"GPS stations measure plate speeds directly: a few centimetres per year, about as fast as fingernails grow."},{"say":"Put in a typical speed and a million years.","tex":"d = 2.5\\ \\text{cm/yr} \\times 1\\,000\\,000\\ \\text{yr} = 2\\,500\\,000\\ \\text{cm}","why":"The years cancel, leaving centimetres."},{"say":"Convert to kilometres.","tex":"2\\,500\\,000\\ \\text{cm} = 25\\,000\\ \\text{m} = 25\\ \\text{km}","why":"Divide by 100 for metres, then by 1000 for kilometres."},{"say":"Run the same sum backwards to date the Atlantic.","tex":"t = \\frac{d}{v} = \\frac{5000\\ \\text{km}}{2.5\\ \\text{cm/yr}} = 200\\ \\text{million years}","why":"5000 km is 5 × 10⁸ cm. This matches the ages of the oldest Atlantic sea-floor rocks."}],"result":"d = vt: \\quad 2.5\\ \\text{cm/yr for } 10^{6}\\ \\text{yr} = 25\\ \\text{km}","assume":["Plate speeds have not been constant over geological time; this is an estimate of scale.","Evidence for moving plates: matching coastlines, fossils and rock types, magnetic stripes on the sea floor, and direct GPS measurement."]},"gcse-measurement":{"steps":[{"say":"Starting and stopping a timer by hand adds the same reaction error whether you time one swing or many.","tex":"t_N = N\\,T \\pm \\Delta t","why":"The error Δt (about 0.2 s) comes from you, not from how long the timing lasts."},{"say":"Divide by the number of swings to get the period.","tex":"T = \\frac{t_N}{N} \\pm \\frac{\\Delta t}{N}","why":"Dividing a measurement by N divides its uncertainty by N as well."},{"say":"Two perpendicular vectors form the two short sides of a right-angled triangle.","tex":"R^2 = F_1^2 + F_2^2 \\;\\Longrightarrow\\; R = \\sqrt{F_1^2 + F_2^2}","why":"Drawing the vectors tip-to-tail, the resultant is the hypotenuse, so Pythagoras applies."},{"say":"The direction comes from the same triangle.","tex":"\\tan\\theta = \\frac{F_2}{F_1}","why":"tan = opposite ÷ adjacent, with θ measured from F₁."}],"result":"T = \\frac{t_N}{N}, \\qquad R = \\sqrt{F_1^2 + F_2^2},\\ \\tan\\theta = \\frac{F_2}{F_1}","assume":["Pythagoras only works for perpendicular vectors; otherwise use a scale drawing or the cosine rule.","Timing more swings does not help if the swings are dying away or you miscount them."]},"gcse-mass-weight":{"steps":[{"say":"Weight is the gravitational force on a mass; it is proportional to the mass.","tex":"W = m g","why":"g is the gravitational field strength: the force on each kilogram, 9.8 N/kg on Earth."},{"say":"Density is mass per unit volume.","tex":"\\rho = \\frac{m}{V}","why":"A definition that lets materials be compared whatever the size of the sample."},{"say":"Convert g/cm³ to kg/m³.","tex":"1\\ \\frac{\\text{g}}{\\text{cm}^3} = \\frac{10^{-3}\\ \\text{kg}}{10^{-6}\\ \\text{m}^3} = 1000\\ \\frac{\\text{kg}}{\\text{m}^3}","why":"1 cm = 10⁻² m, so 1 cm³ = (10⁻²)³ m³ = 10⁻⁶ m³. A million cubic centimetres fit in a cubic metre."},{"say":"Combine the two to get the weight of a volume of material.","tex":"W = \\rho V g","why":"Substitute m = ρV into W = mg. This form is the starting point for liquid pressure and upthrust."}],"result":"W = mg, \\qquad \\rho = \\frac{m}{V}, \\qquad W = \\rho V g","assume":["Mass is the same everywhere; weight depends on g, which varies slightly over Earth and greatly between planets.","A balance compares masses and reads the same on the Moon; a spring scale measures weight and does not."]},"gcse-forces":{"steps":[{"say":"Loading a spring: equal extra loads give equal extra extensions.","tex":"F \\propto x \\;\\Longrightarrow\\; F = kx","why":"The load–extension graph is a straight line through the origin; its gradient is the spring constant k."},{"say":"Experiments with trolleys: acceleration is proportional to resultant force.","tex":"a \\propto F \\quad (m \\text{ fixed})","why":"Double the pulling force on the same trolley and the acceleration doubles."},{"say":"And inversely proportional to mass.","tex":"a \\propto \\frac{1}{m} \\quad (F \\text{ fixed})","why":"The same force on double the mass gives half the acceleration."},{"say":"Combine the two proportionalities; the newton is defined so that the constant is 1.","tex":"a = \\frac{F}{m} \\;\\Longrightarrow\\; F = ma","why":"1 N is the force that gives 1 kg an acceleration of 1 m/s², so no extra constant appears."}],"result":"F = kx \\ (\\text{below the limit of proportionality}), \\qquad F_{\\text{res}} = ma","assume":["Hooke’s law fails beyond the limit of proportionality; past the elastic limit the spring is permanently stretched.","F must be the resultant force. F = ma assumes constant mass and speeds far below that of light."]},"gcse-moments":{"steps":[{"say":"The turning effect of a force depends on its size and on how far from the pivot it acts.","tex":"M = F\\,d_{\\perp}","why":"d⊥ is the perpendicular distance from the pivot to the line of the force. A long spanner needs less force."},{"say":"A balanced beam does not start to turn, so turning effects one way cancel those the other way.","tex":"\\sum M_{\\text{clockwise}} = \\sum M_{\\text{anticlockwise}}","why":"If one side were larger, the beam would start rotating that way."},{"say":"For two weights on a see-saw this gives a simple rule.","tex":"W_1 d_1 = W_2 d_2 \\;\\Longrightarrow\\; d_2 = \\frac{W_1 d_1}{W_2}","why":"A heavier person must sit closer to the pivot."},{"say":"It must also not move up or down, so the forces balance too.","tex":"\\sum F_{\\text{up}} = \\sum F_{\\text{down}}","why":"The pivot pushes up with a force equal to the total weight. Two conditions are needed for equilibrium, not one."}],"result":"M = Fd_{\\perp}; \\quad \\text{equilibrium: } \\sum M_{\\text{cw}} = \\sum M_{\\text{acw}} \\text{ and } \\sum F = 0","assume":["The beam’s own weight acts at its centre of gravity and must be included unless the pivot is there.","Balanced does not have to mean horizontal: the rule holds for a beam at rest at any angle."]},"gcse-work-power":{"steps":[{"say":"Work is the energy transferred when a force moves something along its own direction.","tex":"W = F d","why":"A definition. No movement, or movement at right angles to the force, means no work."},{"say":"Power is the rate of doing work.","tex":"P = \\frac{W}{t}","why":"The same job done in half the time needs twice the power. 1 W = 1 J/s."},{"say":"Substitute W = Fd.","tex":"P = \\frac{F d}{t}","why":"Just replacing W."},{"say":"Recognise d/t as the speed.","tex":"P = F v","why":"At steady speed v the object covers d = vt, so power = force × speed. This is why a car’s top speed is set by its engine power."}],"result":"W = Fd, \\qquad P = \\frac{W}{t} = Fv, \\qquad \\text{efficiency} = \\frac{\\text{useful out}}{\\text{total in}}","assume":["W = Fd needs a constant force along the motion; otherwise use the component along the motion, or the area under a force–distance graph.","P = Fv gives the power at that instant; if the speed changes, so does the power."]},"gcse-resources":{"steps":[{"say":"Water falling through a height h gives up gravitational potential energy.","tex":"E = m g h","why":"Each kilogram loses gh joules as it drops h metres."},{"say":"Power is energy per second, so use the mass arriving each second.","tex":"P = \\frac{m g h}{t}","why":"Divide the energy by the time taken."},{"say":"Write the mass per second using density and volume flow rate Q.","tex":"\\frac{m}{t} = \\rho Q \\;\\Longrightarrow\\; P = \\rho Q g h","why":"Mass = density × volume, and Q is the volume passing per second (m³/s)."},{"say":"Only a fraction becomes electrical power.","tex":"P_{\\text{electrical}} = \\text{efficiency} \\times \\rho Q g h","why":"Turbines and generators waste some energy as heat and leave the water with some kinetic energy. Large hydro plants reach about 90%."}],"result":"P_{\\text{electrical}} = \\eta\\,\\rho Q g h, \\qquad E = Pt","assume":["Assumes the full head h is available at the turbine; friction in pipes reduces it.","Comparing resources also needs reliability, cost, land use and emissions, none of which are in this equation."]},"gcse-pressure":{"steps":[{"say":"Pressure is force per unit area.","tex":"p = \\frac{F}{A}","why":"The same force spread over a larger area presses less hard: snowshoes versus stilettos."},{"say":"Consider a column of liquid of height h and base area A. Its weight presses on the base.","tex":"F = m g = \\rho V g = \\rho (A h) g","why":"Mass = density × volume, and the volume of a column is base area × height."},{"say":"Divide by the base area.","tex":"p = \\frac{\\rho A h g}{A} = \\rho g h","why":"The area cancels, so the pressure depends only on depth and density, not on the shape or width of the container."},{"say":"Between two depths the pressure differs by the weight of the liquid in between.","tex":"\\Delta p = \\rho g\\,\\Delta h","why":"Apply the previous line to each depth and subtract. Any pressure on the surface (the atmosphere) cancels in the difference."}],"result":"p = \\frac{F}{A}, \\qquad \\Delta p = \\rho g \\Delta h","assume":["Assumes constant density: fine for liquids, not for the atmosphere, where the air thins with height.","Total pressure at depth is atmospheric pressure plus ρgh."]},"gcse-particles":{"steps":[{"say":"Gas pressure is the force of particles hitting the walls, per unit area.","tex":"p = \\frac{F}{A}","why":"Each collision gives the wall a tiny push; billions per second make a steady force."},{"say":"Squeeze a gas to half the volume at the same temperature: the same particles hit each bit of wall twice as often.","tex":"V \\rightarrow \\tfrac12 V \\;\\Longrightarrow\\; p \\rightarrow 2p","why":"The particles are twice as crowded but, at the same temperature, no faster."},{"say":"So pressure is inversely proportional to volume.","tex":"p \\propto \\frac{1}{V} \\;\\Longrightarrow\\; pV = \\text{constant}","why":"This is Boyle’s law, found by experiment in 1662."},{"say":"Compare two states of the same gas.","tex":"p_1 V_1 = p_2 V_2","why":"The constant is the same before and after, provided no gas escapes and the temperature is unchanged."},{"say":"Cooling slows the particles. Extrapolating, they would stop at −273 °C, which defines the kelvin scale.","tex":"T\\,(\\text{K}) = \\theta\\,(^\\circ\\text{C}) + 273","why":"A graph of gas pressure against temperature is a straight line that reaches zero at −273 °C: absolute zero."}],"result":"p_1V_1 = p_2V_2 \\ (\\text{fixed mass and temperature}), \\qquad T = \\theta + 273","assume":["Fixed mass of gas at constant temperature; compress it quickly and it heats up, breaking the law.","Real gases deviate at high pressure or near the temperature at which they liquefy."]},"gcse-expansion":{"steps":[{"say":"Heating makes particles vibrate more and sit, on average, further apart.","tex":"T \\uparrow \\;\\Longrightarrow\\; \\text{mean separation} \\uparrow","why":"The force between neighbouring particles is lopsided: easier to pull apart than to push together, so bigger vibrations shift the average outward."},{"say":"Every metre of a rod expands by the same amount, so the total expansion is proportional to the original length.","tex":"\\Delta L \\propto L_0","why":"A 2 m rod is two 1 m rods end to end, each growing equally."},{"say":"It is also proportional to the temperature rise.","tex":"\\Delta L \\propto \\Delta T","why":"Found by experiment for moderate temperature changes."},{"say":"Combine with a constant α that depends on the material.","tex":"\\Delta L = \\alpha L_0 \\Delta T","why":"α is the fractional change in length per degree: about 1.2 × 10⁻⁵ per °C for steel."}],"result":"\\Delta L = \\alpha L_0 \\Delta T","assume":["α is roughly constant only over a limited temperature range.","Water between 0 °C and 4 °C contracts on heating, which is why ice forms on top of ponds."]},"gcse-heat-transfer":{"steps":[{"say":"An object at steady temperature takes in energy as fast as it gives it out.","tex":"P_{\\text{absorbed}} = P_{\\text{emitted}}","why":"If absorption were faster the object would warm; if slower it would cool."},{"say":"Every square metre of a hot surface radiates, and far more strongly at higher temperature.","tex":"P_{\\text{emitted}} = \\varepsilon \\sigma A T^4","why":"The Stefan–Boltzmann law: T in kelvin, ε between 0 (perfect reflector) and 1 (perfect black body)."},{"say":"Apply this to Earth: sunlight is absorbed over a disc, infrared is emitted from the whole sphere.","tex":"S (1 - a)\\,\\pi R^2 = \\sigma \\, 4\\pi R^2 \\, T^4","why":"Earth blocks a disc of sunlight of area πR²; a fraction a (the albedo, about 0.3) is reflected. It radiates from its full surface 4πR²."},{"say":"Solve for the temperature.","tex":"T = \\left[\\frac{S(1-a)}{4\\sigma}\\right]^{1/4} \\approx 255\\ \\text{K}","why":"With S = 1360 W/m². That is −18 °C, about 33 °C colder than the real surface; the difference is the greenhouse effect."}],"result":"P_{\\text{absorbed}} = P_{\\text{emitted}}, \\qquad P = \\varepsilon\\sigma A T^4","assume":["The T⁴ law is beyond most GCSE courses; the balance idea is the examinable part.","Treats Earth as one uniform temperature with no atmosphere."]},"gcse-waves":{"steps":[{"say":"In one period T the source makes one complete wave, and that wave moves forward exactly one wavelength.","tex":"\\text{distance} = \\lambda \\quad \\text{in time } T","why":"The next crest is produced one period later, by which time the first has moved on by the crest spacing."},{"say":"Speed is distance over time.","tex":"v = \\frac{\\lambda}{T}","why":"Applying v = d/t to one wavelength."},{"say":"Frequency is the number of waves per second.","tex":"f = \\frac{1}{T}","why":"If each wave takes T seconds, then 1/T of them pass per second."},{"say":"Substitute.","tex":"v = f\\lambda","why":"Replacing 1/T by f. Each second, f waves each of length λ pass a point."}],"result":"v = f\\lambda","assume":["The speed is set by the medium, the frequency by the source: when a wave enters a new medium, λ changes and f does not.","True for all waves: water, sound, light, waves on strings."]},"gcse-reflection-refraction":{"steps":[{"say":"A wavefront crosses into glass at an angle; the end that enters first slows down first.","tex":"v_{\\text{glass}} < v_{\\text{air}}","why":"In the same time, the part still in air travels further than the part already in glass, so the wavefront swings round."},{"say":"In time t the two ends travel v₁t and v₂t; geometry of the two right-angled triangles sharing the boundary gives the angles.","tex":"\\frac{\\sin i}{\\sin r} = \\frac{v_{\\text{air}}\\,t}{v_{\\text{glass}}\\,t} = \\frac{v_{\\text{air}}}{v_{\\text{glass}}}","why":"Each distance is the opposite side of a triangle whose hypotenuse is the same stretch of boundary."},{"say":"This ratio is a constant for the material, called the refractive index.","tex":"n = \\frac{\\sin i}{\\sin r} = \\frac{c}{v}","why":"Snell’s law. n = 1.5 for glass means light travels 1.5 times slower in it."},{"say":"Going from glass to air, the ray bends away from the normal. At the critical angle it runs along the surface.","tex":"n = \\frac{\\sin 90^\\circ}{\\sin c} \\;\\Longrightarrow\\; \\sin c = \\frac{1}{n}","why":"Reverse the ray: the angle in air is 90°, the angle in glass is c. Beyond c no refracted ray exists and all the light reflects."}],"result":"n = \\frac{\\sin i}{\\sin r} = \\frac{c}{v}, \\qquad \\sin c = \\frac{1}{n}","assume":["n depends slightly on colour, which is what causes dispersion.","Total internal reflection only happens going from the slower medium towards the faster one."]},"gcse-lenses":{"steps":[{"say":"Draw two rays from the top of the object: one through the centre of the lens (undeviated), one parallel to the axis (refracted through the focus).","tex":"\\text{image is where the two rays meet}","why":"Any two rays from the same point locate its image."},{"say":"The central ray makes similar triangles on either side of the lens.","tex":"\\frac{h_i}{h_o} = \\frac{v}{u}","why":"Same angle at the lens centre, so heights are in the same ratio as distances. This ratio is the magnification."},{"say":"The ray through the focus makes another pair of similar triangles.","tex":"\\frac{h_i}{h_o} = \\frac{v - f}{f}","why":"One triangle has height h_o and base f (lens to focus); the other has height h_i and base v − f."},{"say":"Set the two expressions equal and divide through by v.","tex":"\\frac{v}{u} = \\frac{v}{f} - 1 \\;\\Longrightarrow\\; \\frac{1}{u} + \\frac{1}{v} = \\frac{1}{f}","why":"Dividing by v gives 1/u = 1/f − 1/v; then move 1/v across."}],"result":"\\frac1f = \\frac1u + \\frac1v, \\qquad m = \\frac{h_i}{h_o} = \\frac{v}{u}","assume":["Thin lens, rays close to the axis. Thick lenses and wide beams give blurred images (aberrations).","Uses the “real is positive” convention: a virtual image has negative v."]},"gcse-sound":{"steps":[{"say":"Sound moves at a steady speed through a given material.","tex":"v = \\frac{d}{t}","why":"Clap far from a wall or time a sound between two microphones."},{"say":"For an echo the sound covers the distance twice.","tex":"v = \\frac{2d}{t} \\;\\Longrightarrow\\; d = \\frac{vt}{2}","why":"There and back. This is how sonar and ultrasound scans measure depth."},{"say":"Like all waves, sound obeys the wave equation.","tex":"v = f\\lambda","why":"Each second f waves of length λ pass."},{"say":"So the wavelengths we can hear span a huge range.","tex":"\\lambda = \\frac{v}{f}: \\quad \\frac{340}{20} = 17\\ \\text{m} \\quad\\text{to}\\quad \\frac{340}{20\\,000} = 1.7\\ \\text{cm}","why":"Hearing runs from 20 Hz to 20 kHz. Ultrasound is above 20 kHz, with short wavelengths that give sharp images."}],"result":"d = \\frac{vt}{2}, \\qquad v = f\\lambda","assume":["The speed depends on the medium and its temperature; in a scan, the speed in tissue (about 1500 m/s) must be used.","The upper limit of hearing falls with age."]},"gcse-static":{"steps":[{"say":"Charge comes in whole numbers of electron charges.","tex":"Q = n e, \\qquad e = 1.6\\times10^{-19}\\ \\text{C}","why":"Rubbing transfers electrons, one at a time, from one surface to the other. Millikan’s oil drops showed charge is always a multiple of e."},{"say":"Electric field strength is the force on each coulomb of charge.","tex":"E = \\frac{F}{Q}","why":"A definition, just as g is the gravitational force on each kilogram."},{"say":"Move a charge Q across the gap d between two parallel plates. The work done is force × distance.","tex":"W = F d = E Q d","why":"Between parallel plates the field, and so the force, is the same everywhere."},{"say":"Voltage is the work done per coulomb. Compare.","tex":"V = \\frac{W}{Q} = E d \\;\\Longrightarrow\\; E = \\frac{V}{d}","why":"So the field between plates is the voltage divided by their separation."}],"result":"Q = ne, \\qquad E = \\frac{F}{Q} = \\frac{V}{d}","assume":["E = V/d is for the uniform field between parallel plates, away from the edges.","Air breaks down and sparks at about 3 × 10⁶ V/m."]},"gcse-current-pd":{"steps":[{"say":"Current is the rate of flow of charge.","tex":"I = \\frac{Q}{t}","why":"1 A means 1 C passing a point each second."},{"say":"That charge is carried by electrons.","tex":"Q = n e \\;\\Longrightarrow\\; I = \\frac{n e}{t}","why":"One amp is about 6 × 10¹⁸ electrons per second."},{"say":"E.m.f. is the energy the source gives to each coulomb.","tex":"\\mathcal{E} = \\frac{W}{Q}","why":"A 1.5 V cell gives every coulomb 1.5 J."},{"say":"Potential difference is the energy each coulomb hands over in a component.","tex":"V = \\frac{W}{Q} \\;\\Longrightarrow\\; W = QV = I t V","why":"Substituting Q = It gives the electrical energy transferred, the basis of P = IV."}],"result":"I = \\frac{Q}{t}, \\qquad V = \\frac{W}{Q}, \\qquad W = IVt","assume":["Conventional current flows from + to −, opposite to the electrons.","A real source has internal resistance, so its terminal p.d. is slightly below its e.m.f. when current flows."]},"gcse-power-cost":{"steps":[{"say":"Voltage is energy per coulomb, current is coulombs per second.","tex":"V = \\frac{W}{Q}, \\qquad I = \\frac{Q}{t}","why":"The two definitions."},{"say":"Multiply them: the charge cancels, leaving energy per second.","tex":"IV = \\frac{Q}{t}\\cdot\\frac{W}{Q} = \\frac{W}{t} = P","why":"Joules per coulomb × coulombs per second = joules per second = watts."},{"say":"Energy is power × time.","tex":"E = Pt = IVt","why":"A 2 kW heater for 3 hours uses 6 kWh."},{"say":"Use V = IR to write the power in a resistor two other ways.","tex":"P = I(IR) = I^2R, \\qquad P = \\frac{V}{R}V = \\frac{V^2}{R}","why":"Replace V, or replace I. I²R explains why transmission cables are run at low current."},{"say":"One kilowatt-hour in joules.","tex":"1\\ \\text{kWh} = 1000\\ \\text{W} \\times 3600\\ \\text{s} = 3.6\\times10^{6}\\ \\text{J}","why":"A kilowatt for an hour."}],"result":"P = IV = I^2R = \\frac{V^2}{R}, \\qquad E = Pt","assume":["I²R and V²/R need the V and I for that one component.","For a.c. mains the quoted 230 V is an effective (r.m.s.) value, and the formulas work as written for heaters and lamps."]},"gcse-series-parallel":{"steps":[{"say":"Series: the same current flows through both, and the voltages add.","tex":"V = V_1 + V_2 = IR_1 + IR_2","why":"Energy per coulomb from the supply is shared between the two components."},{"say":"Divide by I to get the total resistance.","tex":"R = \\frac{V}{I} = R_1 + R_2","why":"Resistors in series simply add."},{"say":"Parallel: the same voltage across both, and the currents add.","tex":"I = I_1 + I_2 = \\frac{V}{R_1} + \\frac{V}{R_2}","why":"Charge is conserved at the junction."},{"say":"Divide by V.","tex":"\\frac{1}{R} = \\frac{I}{V} = \\frac{1}{R_1} + \\frac{1}{R_2}","why":"The total is always less than the smallest branch."},{"say":"Two series resistors share the supply voltage in proportion to their resistances.","tex":"V_{\\text{out}} = I R_2 = \\frac{V_{\\text{in}}}{R_1 + R_2}\\,R_2","why":"The current is V_{in}/(R₁ + R₂); the output is taken across R₂. This is the potential divider."}],"result":"R_{\\text{series}} = R_1 + R_2, \\quad \\frac{1}{R_{\\text{par}}} = \\frac{1}{R_1} + \\frac{1}{R_2}, \\quad V_{\\text{out}} = V_{\\text{in}}\\frac{R_2}{R_1 + R_2}","assume":["The divider formula assumes nothing draws significant current from the output.","Ohmic components at constant temperature; an LDR or thermistor changes R with light or temperature, which is how sensors work."]},"gcse-safety":{"steps":[{"say":"An appliance of power P on the mains draws a current set by P = IV.","tex":"I = \\frac{P}{V}","why":"For a 2300 W kettle on 230 V: I = 10 A."},{"say":"Choose the fuse just above the normal current.","tex":"I_{\\text{fuse}} > I_{\\text{normal}}: \\quad 10\\ \\text{A} \\rightarrow 13\\ \\text{A fuse}","why":"It must carry the working current without melting, but melt quickly if a fault makes the current much larger."},{"say":"A cable of resistance R is heated by the current through it.","tex":"P_{\\text{heat}} = I^2 R","why":"Doubling the current quadruples the heating, which is why overloaded sockets and thin cables are fire risks."},{"say":"If the live wire touches an earthed metal case, a low-resistance path gives a huge current.","tex":"I_{\\text{fault}} = \\frac{230\\ \\text{V}}{R_{\\text{earth path}}} \\gg I_{\\text{fuse}}","why":"The earth wire has a very low resistance, so the fuse blows and disconnects the live side before anyone touches the case."}],"result":"I = \\frac{P}{V}; \\quad \\text{fuse rating just above } I; \\quad P_{\\text{heat}} = I^2R","assume":["A fuse protects the cable and prevents fires; it is too slow to protect a person. Residual-current devices do that.","The fuse must be in the live wire, or the appliance stays live after it blows."]},"gcse-electromagnets":{"steps":[{"say":"The field around a long straight wire forms circles; it is stronger for larger currents and weaker further away.","tex":"B \\propto \\frac{I}{r}","why":"The same current’s effect is spread round a circle of circumference 2πr."},{"say":"With the constant of proportionality:","tex":"B = \\frac{\\mu_0 I}{2\\pi r}","why":"μ₀ = 4π × 10⁻⁷ T m/A. Beyond GCSE, but it shows where the 1/r comes from."},{"say":"Wind the wire into a solenoid. Inside, the fields from all turns point the same way and add.","tex":"B \\propto (\\text{turns per metre}) \\times I","why":"Outside they largely cancel, so the field is strong and uniform inside, weak outside."},{"say":"So for n turns per metre:","tex":"B = \\mu_0 n I","why":"The field does not depend on the solenoid’s radius, only on how tightly it is wound and the current."}],"result":"B_{\\text{wire}} = \\frac{\\mu_0 I}{2\\pi r}, \\qquad B_{\\text{solenoid}} = \\mu_0 n I","assume":["Long wire and long solenoid; near the ends the solenoid field falls to about half.","An iron core multiplies the field by hundreds or thousands until it saturates."]},"gcse-motor":{"steps":[{"say":"A wire of length L carrying current I at right angles to a field B feels a force.","tex":"F = BIL","why":"The wire’s own field adds to the magnet’s on one side and cancels on the other, pushing the wire sideways. Direction: Fleming’s left-hand rule."},{"say":"In a rectangular coil the two long sides carry current in opposite directions, so their forces are opposite.","tex":"F_{\\text{left}} = -F_{\\text{right}}","why":"One side is pushed up and the other down: a pair of forces that turns the coil."},{"say":"Each force acts at half the coil’s width w from the axle, giving a turning moment.","tex":"\\tau = 2 \\times BIL \\times \\frac{w}{2} = BI(Lw) = BIA","why":"Moment = force × perpendicular distance, largest when the coil lies flat in the field. Lw is the coil’s area A."},{"say":"With N turns the moments add.","tex":"\\tau_{\\max} = NBIA","why":"Every turn feels the same forces. More turns, more current, stronger field or bigger coil all make it turn harder."}],"result":"F = BIL, \\qquad \\tau_{\\max} = NBIA","assume":["The turning effect falls to zero when the coil is at right angles to the field; the split-ring commutator reverses the current there so rotation continues.","A spinning motor generates a back-e.m.f. that reduces the current: I = (V − E_{back})/R."]},"gcse-induction":{"steps":[{"say":"A wire of length L moves at speed v across a field B. The charges inside move with it and feel a force along the wire.","tex":"F = B q v","why":"A moving charge in a magnetic field is pushed at right angles to both its motion and the field."},{"say":"Pushing a charge along the length of the wire does work.","tex":"W = F L = B q v L","why":"Work = force × distance moved along the force."},{"say":"E.m.f. is work per unit charge.","tex":"\\mathcal{E} = \\frac{W}{q} = BLv","why":"The charge cancels. Faster motion, longer wire or stronger field all give a larger e.m.f."},{"say":"BLv is the rate at which the wire sweeps out magnetic flux.","tex":"\\mathcal{E} = \\frac{B\\,(L\\,v\\,\\Delta t)}{\\Delta t} = \\frac{\\Delta\\Phi}{\\Delta t}, \\qquad N \\text{ turns: } \\mathcal{E} = N\\frac{\\Delta\\Phi}{\\Delta t}","why":"In time Δt the wire sweeps area LvΔt, cutting flux B × area. This is Faraday’s law."}],"result":"\\mathcal{E} = BLv = N\\frac{\\Delta\\Phi}{\\Delta t}","assume":["Wire, motion and field mutually at right angles; otherwise only the perpendicular parts count.","Lenz’s law gives the direction: the induced current opposes the change causing it, as energy conservation requires."]},"gcse-transformer":{"steps":[{"say":"The alternating current in the primary makes a changing flux in the iron core, and the same flux passes through every turn of both coils.","tex":"V_p = N_p \\frac{\\Delta\\Phi}{\\Delta t}, \\qquad V_s = N_s \\frac{\\Delta\\Phi}{\\Delta t}","why":"Faraday’s law for each coil. The iron core guides almost all the flux through both."},{"say":"Divide one by the other.","tex":"\\frac{V_p}{V_s} = \\frac{N_p}{N_s}","why":"The rate of change of flux cancels: voltage per turn is the same in both coils."},{"say":"If no energy is lost, power in equals power out.","tex":"V_p I_p = V_s I_s","why":"Conservation of energy for an ideal (100% efficient) transformer. Raising the voltage lowers the current."},{"say":"Cables of resistance R waste power as heat.","tex":"P_{\\text{loss}} = I^2 R = \\left(\\frac{P}{V}\\right)^2 R","why":"For the same delivered power P, ten times the voltage means a tenth of the current and a hundredth of the loss."}],"result":"\\frac{V_p}{V_s} = \\frac{N_p}{N_s}, \\qquad V_pI_p = V_sI_s, \\qquad P_{\\text{loss}} = I^2R","assume":["Works only with a.c.: a steady current gives no changing flux.","Real transformers lose a few per cent to coil resistance, eddy currents and core magnetisation."]},"gcse-atom":{"steps":[{"say":"Most alpha particles pass straight through gold foil, so the atom is mostly empty space.","tex":"\\text{most } \\alpha: \\text{undeflected}","why":"Geiger and Marsden, 1909. A solid “plum pudding” atom would have slowed or stopped them."},{"say":"A very few bounce back, so the positive charge and nearly all the mass sit in a tiny nucleus.","tex":"r_{\\text{nucleus}} \\sim 10^{-15}\\ \\text{m} \\approx \\frac{r_{\\text{atom}}}{100\\,000}","why":"Only a small, dense, positive target could turn a fast alpha right round, and only rarely would one hit it."},{"say":"A nucleus contains Z protons and N neutrons.","tex":"A = Z + N, \\qquad {}^{A}_{Z}\\mathrm{X}","why":"A counts the nucleons. Isotopes have the same Z, so the same chemistry, but different N."},{"say":"In any nuclear change, nucleon number and charge are conserved.","tex":"\\sum A_{\\text{before}} = \\sum A_{\\text{after}}, \\qquad \\sum Z_{\\text{before}} = \\sum Z_{\\text{after}}","why":"Nucleons are not created or destroyed, and nor is charge. This lets you find the missing product in a fission or fusion equation."}],"result":"A = Z + N; \\quad A \\text{ and } Z \\text{ both balance in nuclear equations}","assume":["The Rutherford picture treats electrons as orbiting dots; the modern description uses electron clouds.","Mass is not exactly conserved: a small amount becomes energy (E = mc²), the source of nuclear power."]},"gcse-radiation":{"steps":[{"say":"A detector counts background radiation as well as the source.","tex":"\\text{corrected count} = \\text{measured} - \\text{background}","why":"Rocks, cosmic rays and food are always there; measure them with the source removed and subtract."},{"say":"Alpha emission removes 2 protons and 2 neutrons.","tex":"{}^{A}_{Z}\\mathrm{X} \\rightarrow {}^{A-4}_{Z-2}\\mathrm{Y} + {}^{4}_{2}\\mathrm{He}","why":"Balance the top numbers (A) and the bottom numbers (Z) separately."},{"say":"Beta emission turns a neutron into a proton and an electron.","tex":"{}^{A}_{Z}\\mathrm{X} \\rightarrow {}^{\\ \\ A}_{Z+1}\\mathrm{Y} + {}^{\\ \\,0}_{-1}\\mathrm{e}","why":"A is unchanged; Z goes up by one because the electron carries charge −1."},{"say":"Gamma rays spread out evenly over a sphere, so the intensity falls as the square of the distance.","tex":"I = \\frac{P}{4\\pi d^2} \\propto \\frac{1}{d^2}","why":"The same energy crosses a sphere of area 4πd². Doubling the distance quarters the dose."}],"result":"\\text{corrected} = \\text{measured} - \\text{background}; \\qquad I \\propto \\frac{1}{d^2}","assume":["The inverse-square law needs a small source and no absorption on the way; alpha is stopped by a few centimetres of air long before it applies.","Counts are random: repeat or count for longer to reduce the scatter."]},"gcse-earth-moon":{"steps":[{"say":"An object going round a circle covers the circumference once per period.","tex":"\\text{distance} = 2\\pi r \\quad \\text{in time } T","why":"One full orbit, or one full rotation."},{"say":"So its speed is:","tex":"v = \\frac{2\\pi r}{T}","why":"Speed = distance ÷ time."},{"say":"Earth’s orbital speed round the Sun.","tex":"v = \\frac{2\\pi \\times 1.5\\times10^{11}\\ \\text{m}}{3.16\\times10^{7}\\ \\text{s}} \\approx 30\\ \\text{km/s}","why":"r is the Earth–Sun distance and T is one year in seconds."},{"say":"The Moon’s orbit takes 27.3 days, but the phases repeat every 29.5 days.","tex":"\\frac{1}{T_{\\text{phases}}} = \\frac{1}{27.3} - \\frac{1}{365.25} \\;\\Longrightarrow\\; T_{\\text{phases}} \\approx 29.5\\ \\text{days}","why":"While the Moon goes round, Earth moves on round the Sun, so the Moon needs about two more days to line up with the Sun again."}],"result":"v = \\frac{2\\pi r}{T}","assume":["Orbits are treated as circles; they are slightly elliptical.","Seasons are caused by the 23.4° tilt of Earth’s axis, not by distance from the Sun: Earth is closest in January."]},"gcse-solar-system":{"steps":[{"say":"Light takes time to cross the Solar System.","tex":"t = \\frac{d}{c} = \\frac{1.5\\times10^{11}}{3.0\\times10^{8}} = 500\\ \\text{s} \\approx 8\\ \\text{min}","why":"Sun to Earth. We see the Sun as it was 8 minutes ago."},{"say":"A planet in a circular orbit has speed:","tex":"v = \\frac{2\\pi r}{T}","why":"Circumference ÷ period."},{"say":"The Sun’s gravity weakens with distance, so outer planets move more slowly.","tex":"v \\propto \\frac{1}{\\sqrt{r}}","why":"From the inverse-square law of gravity (derived at A-Level): four times as far out, half the speed."},{"say":"Combine the two.","tex":"T = \\frac{2\\pi r}{v} \\propto r^{3/2} \\;\\Longrightarrow\\; T^2 \\propto r^3","why":"Further planets have further to go and go more slowly. This is Kepler’s third law."}],"result":"t = \\frac{d}{c}, \\qquad v = \\frac{2\\pi r}{T}, \\qquad T^2 \\propto r^3","assume":["Real orbits are ellipses with the Sun at one focus; a planet moves fastest when closest.","T² ∝ r³ compares objects orbiting the same central body."]},"gcse-stars":{"steps":[{"say":"A star is stable when the outward pressure from fusion balances the inward pull of gravity.","tex":"\\text{pressure outward} = \\text{gravity inward}","why":"If fusion slows, gravity squeezes and heats the core, speeding fusion up again: a self-correcting balance."},{"say":"Fusing hydrogen to helium loses a little mass.","tex":"4\\,{}^{1}\\mathrm{H} \\rightarrow {}^{4}\\mathrm{He}: \\quad \\Delta m \\approx 0.7\\%","why":"A helium nucleus has slightly less mass than the four protons that built it."},{"say":"The missing mass appears as energy.","tex":"E = \\Delta m\\,c^2","why":"Einstein’s relation. c² is huge, so a small mass gives an enormous energy."},{"say":"The Sun radiates 3.8 × 10²⁶ W, so it loses mass at a calculable rate.","tex":"\\frac{\\Delta m}{t} = \\frac{P}{c^2} = \\frac{3.8\\times10^{26}}{(3.0\\times10^{8})^2} \\approx 4\\times10^{9}\\ \\text{kg/s}","why":"Four million tonnes every second, yet over ten billion years that is less than 0.1% of its mass."}],"result":"E = \\Delta m\\,c^2; \\quad \\text{stable star: pressure balances gravity}","assume":["What a star becomes depends on its mass: Sun-like stars end as white dwarfs; much heavier ones explode as supernovae, leaving neutron stars or black holes.","Elements heavier than iron are made in supernovae and neutron-star mergers, not by ordinary fusion."]},"al-units":{"steps":[{"say":"Multiply two measured quantities, each slightly uncertain.","tex":"z + \\Delta z = (a + \\Delta a)(b + \\Delta b) = ab + a\\,\\Delta b + b\\,\\Delta a + \\Delta a\\,\\Delta b","why":"Take the worst case, with both errors pushing the same way, and expand the brackets."},{"say":"Drop the product of two small quantities and divide by z = ab.","tex":"\\frac{\\Delta z}{z} \\approx \\frac{\\Delta a}{a} + \\frac{\\Delta b}{b}","why":"If each uncertainty is a few per cent, their product is a few hundredths of a per cent. Fractional uncertainties add for products, and the same result holds for quotients."},{"say":"A power is a repeated product.","tex":"z = a^n \\;\\Longrightarrow\\; \\frac{\\Delta z}{z} = n\\,\\frac{\\Delta a}{a}","why":"aⁿ is a multiplied by itself n times, so its fractional uncertainty is added n times. This is why a quantity that is squared or cubed should be measured most carefully."},{"say":"For sums and differences the absolute uncertainties add.","tex":"z = a \\pm b \\;\\Longrightarrow\\; \\Delta z = \\Delta a + \\Delta b","why":"Worst case again: the errors may combine either way, even in a subtraction. A small difference of two large numbers can therefore be very uncertain."},{"say":"A vector at angle θ to the x-axis splits into perpendicular components.","tex":"F_x = F\\cos\\theta, \\qquad F_y = F\\sin\\theta, \\qquad F = \\sqrt{F_x^2 + F_y^2}","why":"The components are the adjacent and opposite sides of a right-angled triangle with F as hypotenuse."}],"result":"\\frac{\\Delta(ab)}{ab} = \\frac{\\Delta a}{a} + \\frac{\\Delta b}{b}, \\qquad \\frac{\\Delta(a^n)}{a^n} = n\\frac{\\Delta a}{a}, \\qquad \\Delta(a \\pm b) = \\Delta a + \\Delta b","assume":["These are worst-case rules for small uncertainties. For independent random errors the proper rule adds in quadrature, which gives a smaller answer.","Systematic errors do not shrink when you repeat readings; only a better method or a calibration removes them."]},"al-kinematics":{"steps":[{"say":"Acceleration is the rate of change of velocity. If it is constant:","tex":"a = \\frac{v - u}{t} \\;\\Longrightarrow\\; v = u + at","why":"Constant acceleration means the v–t graph is a straight line of gradient a starting at u."},{"say":"Displacement is the area under the v–t graph, here a trapezium.","tex":"s = \\tfrac12 (u + v)\\,t","why":"Average of the parallel sides times the width; equivalently, average velocity × time."},{"say":"Substitute v = u + at.","tex":"s = \\tfrac12 (u + u + at)\\,t = ut + \\tfrac12 a t^2","why":"The area is a rectangle ut plus a triangle of base t and height at."},{"say":"Eliminate t instead, using t = (v − u)/a.","tex":"s = \\tfrac12 (u + v)\\,\\frac{v - u}{a} = \\frac{v^2 - u^2}{2a}","why":"(v + u)(v − u) is a difference of two squares."},{"say":"Rearrange.","tex":"v^2 = u^2 + 2as","why":"The one equation without time; multiplied by ½m it is the work–energy theorem."}],"result":"v = u + at, \\quad s = \\tfrac12(u + v)t, \\quad s = ut + \\tfrac12at^2, \\quad v^2 = u^2 + 2as","assume":["Only for constant acceleration. If a varies, use gradients and areas of graphs, or calculus.","s, u, v and a are vectors along one line: choose a positive direction and keep to it."]},"al-dynamics":{"steps":[{"say":"Newton’s second law in its general form: force is the rate of change of momentum.","tex":"F = \\frac{\\Delta p}{\\Delta t}, \\qquad p = mv","why":"This is the definition of resultant force. It also covers cases where the mass changes."},{"say":"If the mass is constant it comes outside the change.","tex":"F = \\frac{m\\,\\Delta v}{\\Delta t} = ma","why":"Δ(mv) = mΔv only when m is constant, and Δv/Δt is the acceleration."},{"say":"A falling object feels its weight down and drag up. For fast motion through air the drag grows as the square of the speed.","tex":"ma = mg - kv^2","why":"Resultant force = weight − drag, taking down as positive. k depends on the shape, the area and the air density."},{"say":"At terminal velocity the acceleration is zero.","tex":"mg = k v_t^2 \\;\\Longrightarrow\\; v_t = \\sqrt{\\frac{mg}{k}}","why":"The speed stops changing when drag equals weight. A heavier object of the same shape must fall faster before its drag matches its weight."}],"result":"F = \\frac{\\Delta p}{\\Delta t} = ma \\ (m \\text{ constant}), \\qquad v_t = \\sqrt{\\frac{mg}{k}}","assume":["Drag ∝ v² holds for turbulent flow (most everyday falling objects); slow motion in a viscous liquid has drag ∝ v instead.","F = ma fails for rockets (changing mass) unless you return to F = Δp/Δt, and at speeds close to c."]},"al-momentum":{"steps":[{"say":"Two bodies collide. By Newton’s third law the forces on them are equal and opposite at every instant.","tex":"F_{12} = -F_{21}","why":"The force of 1 on 2 and of 2 on 1 are a third-law pair."},{"say":"They act for the same time, so the changes of momentum are equal and opposite.","tex":"\\Delta p_2 = F_{12}\\,\\Delta t = -F_{21}\\,\\Delta t = -\\Delta p_1","why":"Impulse = force × time = change of momentum, from the second law."},{"say":"So the total momentum does not change.","tex":"m_1u_1 + m_2u_2 = m_1v_1 + m_2v_2","why":"Δp₁ + Δp₂ = 0. This holds whether or not kinetic energy is conserved."},{"say":"In an elastic collision kinetic energy is conserved too. Write both laws with body 1 on the left.","tex":"m_1(u_1 - v_1) = m_2(v_2 - u_2), \\qquad m_1(u_1^2 - v_1^2) = m_2(v_2^2 - u_2^2)","why":"Rearranged momentum conservation, and kinetic energy conservation with the ½ cancelled."},{"say":"Divide the second by the first.","tex":"u_1 + v_1 = v_2 + u_2 \\;\\Longrightarrow\\; u_1 - u_2 = v_2 - v_1","why":"Each side is a difference of two squares. The speed of approach equals the speed of separation."}],"result":"\\sum p_{\\text{before}} = \\sum p_{\\text{after}}; \\qquad \\text{elastic: } u_1 - u_2 = v_2 - v_1","assume":["Needs no resultant external force during the collision (or a collision so brief that external impulses are negligible).","Momentum is a vector: in two dimensions it is conserved separately along each axis."]},"al-equilibrium":{"steps":[{"say":"A couple is two equal, opposite forces F a distance d apart. Take moments about any point O, a distance x from one of them.","tex":"\\tau = Fx + F(d - x)","why":"Both forces turn the object the same way about O."},{"say":"Simplify.","tex":"\\tau = Fd","why":"x cancels: the torque of a couple is the same about every point, and its resultant force is zero, so it turns without pushing."},{"say":"For equilibrium nothing accelerates and nothing starts to rotate.","tex":"\\sum F_x = 0, \\qquad \\sum F_y = 0, \\qquad \\sum M = 0","why":"No resultant force in either direction, and no resultant moment about any point."},{"say":"Example: a weight W hangs from the middle of a string whose two halves make an angle θ with the horizontal.","tex":"2T\\sin\\theta = W \\;\\Longrightarrow\\; T = \\frac{W}{2\\sin\\theta}","why":"Vertical components of the two tensions support the weight; the horizontal components cancel by symmetry."}],"result":"\\tau_{\\text{couple}} = Fd; \\qquad \\sum \\mathbf{F} = 0 \\ \\text{and}\\ \\sum M = 0","assume":["As θ → 0 the tension grows without limit: a loaded string can never be perfectly straight.","Three non-parallel forces in equilibrium must pass through one point and form a closed vector triangle."]},"al-fluids":{"steps":[{"say":"Pressure in a liquid increases with depth.","tex":"\\Delta p = \\rho g\\,\\Delta h","why":"From the weight of a column of liquid divided by its base area."},{"say":"Submerge an upright cylinder of cross-section A, with its top at depth h₁ and its bottom at depth h₂. The liquid pushes up on the bottom harder than it pushes down on the top.","tex":"F_{\\text{up}} = (p_2 - p_1)A = \\rho g\\,(h_2 - h_1)\\,A","why":"The sideways forces cancel in pairs; only the top and bottom faces matter."},{"say":"Recognise the volume of the cylinder.","tex":"F_{\\text{up}} = \\rho g V","why":"(h₂ − h₁)A is its volume, so the upthrust equals the weight of liquid displaced: Archimedes’ principle."},{"say":"A floating body is in equilibrium: upthrust on the submerged part equals its whole weight.","tex":"\\rho_{\\text{fluid}}\\, g\\, V_{\\text{sub}} = \\rho_{\\text{body}}\\, g\\, V \\;\\Longrightarrow\\; \\frac{V_{\\text{sub}}}{V} = \\frac{\\rho_{\\text{body}}}{\\rho_{\\text{fluid}}}","why":"g cancels. Ice of density 917 kg m⁻³ floats with 92% of its volume below fresh water."}],"result":"F_{\\text{up}} = \\rho_{\\text{fluid}}\\, g\\, V_{\\text{displaced}}","assume":["The result holds for any shape: slice the body into thin vertical columns and apply the argument to each.","Assumes the fluid’s density is constant over the height of the object; not true for a tall balloon in the atmosphere."]},"al-energy":{"steps":[{"say":"Only the component of a force along the displacement does work.","tex":"W = F s \\cos\\theta","why":"F cos θ is the component of F along the motion. A force at right angles to the motion does no work."},{"say":"A constant resultant force accelerates a mass from u to v over a distance s.","tex":"W = Fs = mas","why":"Newton’s second law, with the force along the motion."},{"say":"Use v² = u² + 2as to replace as.","tex":"W = m\\,\\frac{v^2 - u^2}{2} = \\tfrac12 mv^2 - \\tfrac12 mu^2","why":"So the work done by the resultant force equals the change in the quantity ½mv², which we call kinetic energy."},{"say":"Lifting a mass at steady speed needs a force mg; the work done is stored as potential energy.","tex":"\\Delta E_p = mg\\,\\Delta h","why":"Force × distance moved in the direction of the force."},{"say":"Power is the rate of doing work.","tex":"P = \\frac{W}{t} = \\frac{Fs}{t} = Fv","why":"s/t is the speed, for a force along the motion."}],"result":"W = Fs\\cos\\theta, \\qquad E_k = \\tfrac12 mv^2, \\qquad \\Delta E_p = mg\\Delta h, \\qquad P = Fv","assume":["ΔE_p = mgΔh assumes g is constant: fine near the Earth’s surface, not for satellites.","The derivation of ½mv² used constant acceleration; calculus shows the result holds for any force."]},"al-materials":{"steps":[{"say":"To compare materials rather than samples, divide the force by the area it acts on, and the extension by the original length.","tex":"\\sigma = \\frac{F}{A}, \\qquad \\varepsilon = \\frac{x}{L}","why":"A thick wire needs more force and a long wire stretches more; stress and strain remove both effects."},{"say":"For a material obeying Hooke’s law, stress is proportional to strain. The constant is the Young modulus.","tex":"E = \\frac{\\sigma}{\\varepsilon} = \\frac{F L}{A x}","why":"E is the gradient of the linear part of the stress–strain graph, in pascals."},{"say":"Compare with F = kx to see what sets a sample’s stiffness.","tex":"k = \\frac{F}{x} = \\frac{EA}{L}","why":"Thicker and shorter means stiffer; E is the part that belongs to the material."},{"say":"The work done stretching the wire is the area under its force–extension graph.","tex":"E_p = \\tfrac12 F x = \\tfrac12 k x^2","why":"The force rises steadily from 0 to F, so the area is a triangle."},{"say":"Divide by the volume AL.","tex":"\\frac{E_p}{AL} = \\tfrac12 \\frac{F}{A}\\cdot\\frac{x}{L} = \\tfrac12 \\sigma\\varepsilon","why":"The energy stored per unit volume is the area under the stress–strain graph."}],"result":"E = \\frac{\\sigma}{\\varepsilon} = \\frac{FL}{Ax}, \\qquad E_p = \\tfrac12 Fx","assume":["Only up to the limit of proportionality. Beyond the elastic limit some of the work is not recovered: the unloading curve returns below the loading curve.","Uses the original area; a ductile metal narrows as it stretches, so the true stress is higher."]},"al-damping":{"steps":[{"say":"A mass on a spring has acceleration proportional to displacement and directed towards the centre.","tex":"a = -\\frac{k}{m}\\,x","why":"From F = −kx and F = ma."},{"say":"Compare with the defining equation of SHM, a = −ω²x.","tex":"\\omega^2 = \\frac{k}{m} \\;\\Longrightarrow\\; f_0 = \\frac{1}{2\\pi}\\sqrt{\\frac{k}{m}}","why":"This is the natural frequency: the one the system chooses when left alone."},{"say":"Light damping removes a fixed fraction of the amplitude in each cycle.","tex":"A = A_0\\,e^{-t/\\tau}","why":"Losing the same fraction in equal times is exponential decay. The frequency hardly changes."},{"say":"The energy of an oscillator is proportional to the square of its amplitude.","tex":"E = \\tfrac12 k A^2 = E_0\\,e^{-2t/\\tau}","why":"At the extremes all the energy is elastic, ½kA². Squaring the amplitude doubles the decay rate."},{"say":"Drive the system at frequency f. The steady amplitude is largest when the driver matches the natural frequency.","tex":"A_{\\max} \\ \\text{at}\\ f \\approx f_0","why":"At resonance the driving force stays in step with the velocity, so it feeds in energy throughout the cycle. Lighter damping gives a taller, sharper peak."}],"result":"f_0 = \\frac{1}{2\\pi}\\sqrt{\\frac{k}{m}}, \\qquad A = A_0 e^{-t/\\tau}, \\qquad \\text{resonance at } f \\approx f_0","assume":["With heavier damping the amplitude peak moves slightly below f₀ and flattens; at critical damping there is no oscillation at all.","Exponential decay assumes a drag force proportional to speed; dry friction makes the amplitude fall linearly."]},"al-waves":{"steps":[{"say":"Two points a distance Δx apart along a wave are out of step by the same fraction of a cycle as Δx is of a wavelength.","tex":"\\frac{\\Delta\\phi}{2\\pi} = \\frac{\\Delta x}{\\lambda} \\;\\Longrightarrow\\; \\Delta\\phi = 2\\pi\\frac{\\Delta x}{\\lambda}","why":"One whole wavelength corresponds to one whole cycle, 2π radians."},{"say":"Intensity is the power crossing unit area at right angles to the wave.","tex":"I = \\frac{P}{A}","why":"A definition, in W m⁻²."},{"say":"A point source radiates equally in all directions, so at distance r its power is spread over a sphere.","tex":"I = \\frac{P}{4\\pi r^2}","why":"The surface area of a sphere is 4πr²: the inverse-square law."},{"say":"Each oscillating particle has energy proportional to the square of its amplitude.","tex":"I \\propto A^2","why":"An oscillator’s energy is ½mω²A². Double the amplitude and the wave carries four times the power."},{"say":"Combine the last two.","tex":"A \\propto \\frac{1}{r}","why":"Intensity falls as 1/r², so the amplitude falls only as 1/r."}],"result":"\\Delta\\phi = 2\\pi\\frac{\\Delta x}{\\lambda}, \\qquad I = \\frac{P}{4\\pi r^2} \\propto A^2","assume":["The inverse-square law needs a point source and no absorption or reflection.","I ∝ A² compares waves of the same frequency in the same medium."]},"al-doppler":{"steps":[{"say":"A source of frequency f_s emits one wavefront every period.","tex":"T = \\frac{1}{f_s}","why":"The definition of period."},{"say":"In that time the previous wavefront has travelled vT, while the source has moved v_s T towards the observer.","tex":"\\lambda_o = vT - v_sT = \\frac{v - v_s}{f_s}","why":"The gap between successive wavefronts ahead of the source is shortened by the distance the source moved."},{"say":"The waves still travel at speed v through the medium, so the observer receives:","tex":"f_o = \\frac{v}{\\lambda_o} = \\frac{f_s\\,v}{v - v_s}","why":"v = fλ at the observer. The wave speed is set by the medium, not by the source’s motion."},{"say":"For a source moving away, the wavefronts are stretched instead.","tex":"f_o = \\frac{f_s\\,v}{v + v_s}","why":"Replace v_s by −v_s: lower pitch."},{"say":"For light, with source speed much less than c:","tex":"\\frac{\\Delta\\lambda}{\\lambda} \\approx \\frac{\\Delta f}{f} \\approx \\frac{v}{c}","why":"Expanding the result for v_s ≪ v. Redshift means the source is receding."}],"result":"f_o = \\frac{f_s\\,v}{v \\mp v_s} \\quad (-\\ \\text{approaching},\\ +\\ \\text{receding})","assume":["Stationary observer and source speed below the wave speed; at v_s = v the wavefronts pile up into a shock wave.","For light there is no medium, and at high speeds the relativistic formula is needed."]},"al-polarisation":{"steps":[{"say":"Polarised light of amplitude A₀ meets a polariser whose axis is at angle θ to its plane of vibration. Resolve the vibration.","tex":"A_{\\parallel} = A_0\\cos\\theta, \\qquad A_{\\perp} = A_0\\sin\\theta","why":"An oscillation is a vector at right angles to the direction of travel, so it has components."},{"say":"Only the component along the axis is transmitted.","tex":"A = A_0\\cos\\theta","why":"The filter absorbs the perpendicular component."},{"say":"Intensity is proportional to amplitude squared.","tex":"I = I_0\\cos^2\\theta","why":"Malus’s law. Crossed polarisers (θ = 90°) transmit nothing."},{"say":"Unpolarised light has every angle equally likely, so average over θ.","tex":"I = I_0\\,\\langle\\cos^2\\theta\\rangle = \\tfrac12 I_0","why":"cos²θ and sin²θ have the same average and add to 1, so each averages ½. An ideal polariser halves the intensity of unpolarised light."}],"result":"I = I_0\\cos^2\\theta; \\qquad \\text{unpolarised: } I = \\tfrac12 I_0","assume":["Only transverse waves can be polarised; sound in air cannot.","Real polarisers absorb a little of the wanted component too."]},"al-stationary":{"steps":[{"say":"Two identical waves travel in opposite directions along a string and superpose.","tex":"y = A\\sin(kx - \\omega t) + A\\sin(kx + \\omega t)","why":"For example a wave and its reflection. k = 2π/λ."},{"say":"Add them using sin P + sin Q = 2 sin ½(P + Q) cos ½(P − Q).","tex":"y = 2A\\sin(kx)\\cos(\\omega t)","why":"The x and t dependence separate: every point oscillates in step, with an amplitude 2A sin kx that depends on where it is."},{"say":"Nodes are where the amplitude is always zero.","tex":"\\sin kx = 0 \\;\\Longrightarrow\\; x = \\frac{n\\lambda}{2}","why":"kx = nπ. Adjacent nodes are half a wavelength apart, with antinodes midway."},{"say":"A string fixed at both ends must have a node at each end.","tex":"L = \\frac{n\\lambda}{2} \\;\\Longrightarrow\\; f_n = \\frac{v}{\\lambda} = \\frac{nv}{2L}","why":"A whole number of half-wavelengths must fit. These are the harmonics."},{"say":"For a string the wave speed depends on tension and mass per unit length.","tex":"v = \\sqrt{\\frac{T}{\\mu}} \\;\\Longrightarrow\\; f_1 = \\frac{1}{2L}\\sqrt{\\frac{T}{\\mu}}","why":"Tighter or lighter strings carry waves faster, so they sound higher."}],"result":"y = 2A\\sin kx\\cos\\omega t; \\qquad \\text{node spacing } \\tfrac12\\lambda; \\qquad f_n = \\frac{nv}{2L}","assume":["A pipe closed at one end has a node there and an antinode at the open end, giving only odd harmonics f = (2n − 1)v/4L.","Real open ends have an end correction: the antinode sits slightly outside the tube."]},"al-current":{"steps":[{"say":"Consider a wire of cross-section A with n charge carriers per unit volume, each of charge q, drifting at speed v.","tex":"\\text{length passing a point in } \\Delta t = v\\,\\Delta t","why":"All the carriers within this length of the point will pass it during Δt."},{"say":"Count them.","tex":"N = n \\times \\text{volume} = n A v\\,\\Delta t","why":"Number per unit volume × volume of that section of wire."},{"say":"The charge that passes is:","tex":"\\Delta Q = N q = n A v q\\,\\Delta t","why":"Each carrier brings charge q."},{"say":"Current is the rate of flow of charge.","tex":"I = \\frac{\\Delta Q}{\\Delta t} = A n v q","why":"Divide by Δt. For copper, n ≈ 8.5 × 10²⁸ m⁻³, so drift speeds are fractions of a millimetre per second."}],"result":"I = Anvq","assume":["v is the average drift velocity, superimposed on random thermal speeds of about 10⁶ m s⁻¹.","Semiconductors have far smaller n, so their carriers drift much faster for the same current."]},"al-resistivity":{"steps":[{"say":"Two identical wires end to end carry the same current and share the voltage.","tex":"R_{2L} = 2R_L \\;\\Longrightarrow\\; R \\propto L","why":"Series resistances add."},{"say":"Two identical wires side by side carry twice the current at the same voltage.","tex":"R_{2A} = \\tfrac12 R_A \\;\\Longrightarrow\\; R \\propto \\frac{1}{A}","why":"Parallel: doubling the area is like adding a second identical path."},{"say":"Combine with a constant that depends only on the material.","tex":"R = \\frac{\\rho L}{A}","why":"ρ is the resistivity, in Ω m."},{"say":"Rearranged, this is how resistivity is measured.","tex":"\\rho = \\frac{RA}{L} = \\frac{R\\,\\pi d^2}{4L}","why":"Plot R against L; the gradient is ρ/A. The diameter is squared, so its uncertainty counts twice."}],"result":"R = \\frac{\\rho L}{A}","assume":["Uniform wire at constant temperature. For metals ρ rises with temperature; for semiconductors it falls.","A filament lamp, a diode and a thermistor are non-ohmic: R = V/I still defines their resistance at each point, but it is not constant."]},"al-dc-circuits":{"steps":[{"say":"A cell of e.m.f. ℰ gives each coulomb ℰ joules. That energy is delivered partly in the external resistance R and partly in the cell’s own internal resistance r.","tex":"\\mathcal{E} = IR + Ir","why":"Kirchhoff’s second law: energy per unit charge is conserved round the loop."},{"say":"The terminal p.d. is what is left for the external circuit.","tex":"V = IR = \\mathcal{E} - Ir","why":"The “lost volts” Ir grow with current. A graph of V against I has gradient −r and intercept ℰ."},{"say":"Solve for the current.","tex":"I = \\frac{\\mathcal{E}}{R + r}","why":"The two resistances are in series."},{"say":"Power delivered to the load:","tex":"P = I^2R = \\frac{\\mathcal{E}^2 R}{(R + r)^2}","why":"Zero when R = 0 (no voltage across the load) and tends to zero for very large R (no current)."},{"say":"It is largest when the load matches the internal resistance.","tex":"\\frac{dP}{dR} = \\mathcal{E}^2\\,\\frac{(r - R)}{(R + r)^3} = 0 \\;\\Longrightarrow\\; R = r","why":"Differentiate using the quotient rule. At this point half the power is wasted inside the cell."}],"result":"V = \\mathcal{E} - Ir, \\qquad P_{\\max} \\ \\text{at}\\ R = r","assume":["Treats r as constant; in a real cell it rises as the cell runs down.","Maximum power transfer is not maximum efficiency: efficiency R/(R + r) approaches 1 only for R ≫ r."]},"al-potential-divider":{"steps":[{"say":"Two resistors in series across a supply carry the same current.","tex":"I = \\frac{V_{\\text{in}}}{R_1 + R_2}","why":"Series resistances add, and no current is taken from the junction."},{"say":"The output is the p.d. across R₂.","tex":"V_{\\text{out}} = I R_2 = V_{\\text{in}}\\,\\frac{R_2}{R_1 + R_2}","why":"V = IR for the lower resistor."},{"say":"Equivalently, the voltages divide in the ratio of the resistances.","tex":"\\frac{V_1}{V_2} = \\frac{IR_1}{IR_2} = \\frac{R_1}{R_2}","why":"Same current in both."},{"say":"Connect a load R_L across R₂: the lower arm becomes a parallel pair.","tex":"R_{\\parallel} = \\frac{R_2 R_L}{R_2 + R_L} < R_2 \\;\\Longrightarrow\\; V_{\\text{out}} \\ \\text{falls}","why":"The load takes current, so the simple formula overestimates the output unless R_L ≫ R₂."},{"say":"A potentiometer wire of uniform resistance per length compares e.m.f.s at balance, when no current flows through the cell being measured.","tex":"\\frac{\\mathcal{E}_1}{\\mathcal{E}_2} = \\frac{l_1}{l_2}","why":"With no current there are no lost volts, so the balance length measures the true e.m.f."}],"result":"V_{\\text{out}} = V_{\\text{in}}\\,\\frac{R_2}{R_1 + R_2}","assume":["Unloaded divider, and a supply with negligible internal resistance.","With a thermistor or LDR in one arm the output follows temperature or light level, but not linearly."]},"al-bfields":{"steps":[{"say":"A wire of length L carrying current I across a field B feels a force BIL. Share it among the carriers in the wire.","tex":"F = BIL, \\qquad I = Anvq, \\qquad N = nAL","why":"N is the number of carriers in the length L."},{"say":"Force on one carrier.","tex":"f = \\frac{BIL}{N} = \\frac{B\\,(Anvq)\\,L}{nAL} = Bqv","why":"Everything about the wire cancels, leaving the force on a single moving charge."},{"say":"This force is always perpendicular to the velocity, so it acts as a centripetal force.","tex":"Bqv = \\frac{mv^2}{r} \\;\\Longrightarrow\\; r = \\frac{mv}{Bq}","why":"It does no work, so the speed stays constant and the path is a circle."},{"say":"The time for one orbit does not depend on the speed.","tex":"T = \\frac{2\\pi r}{v} = \\frac{2\\pi m}{Bq}","why":"Faster particles move in proportionally larger circles. The cyclotron relies on this."},{"say":"In a conducting slab of thickness t and width d, carriers pile up on one edge until the electric force balances the magnetic force.","tex":"q\\frac{V_H}{d} = Bqv, \\quad v = \\frac{I}{n\\,(td)\\,q} \\;\\Longrightarrow\\; V_H = \\frac{BI}{ntq}","why":"The Hall voltage. Using I = Anvq with A = td, the width cancels."}],"result":"F = Bqv, \\qquad r = \\frac{mv}{Bq}, \\qquad V_H = \\frac{BI}{ntq}","assume":["Velocity perpendicular to B; otherwise use Bqv sin θ and the path is a helix.","T = 2πm/Bq fails once the particle is relativistic: its effective inertia grows and it falls out of step."]},"al-ac":{"steps":[{"say":"A sinusoidal current flows through a resistor.","tex":"I = I_0\\sin\\omega t","why":"Mains supply and generator output have this form."},{"say":"The power at each instant:","tex":"P = I^2R = I_0^2 R\\,\\sin^2\\omega t","why":"Never negative: the resistor heats whichever way the current flows."},{"say":"Average over a whole cycle.","tex":"\\langle\\sin^2\\omega t\\rangle = \\tfrac12 \\;\\Longrightarrow\\; \\langle P\\rangle = \\tfrac12 I_0^2 R","why":"sin² = ½(1 − cos 2ωt), and the cosine averages to zero. The mean power is half the peak power."},{"say":"Define the steady current that would give the same heating.","tex":"I_{\\text{rms}}^2 R = \\tfrac12 I_0^2 R \\;\\Longrightarrow\\; I_{\\text{rms}} = \\frac{I_0}{\\sqrt2}","why":"Root of the mean of the square. The same argument gives V_{rms} = V₀/√2."},{"say":"So mains quoted as 230 V has a peak of:","tex":"V_0 = \\sqrt2 \\times 230\\ \\text{V} \\approx 325\\ \\text{V}","why":"Quoted a.c. values are r.m.s. unless stated otherwise."}],"result":"I_{\\text{rms}} = \\frac{I_0}{\\sqrt2}, \\qquad \\langle P\\rangle = I_{\\text{rms}}V_{\\text{rms}} = \\tfrac12 I_0V_0","assume":["The factor √2 is for sine waves only; a square wave has I_{rms} = I₀.","⟨P⟩ = I_{rms} V_{rms} assumes a pure resistance, with current and voltage in phase."]},"al-temperature":{"steps":[{"say":"The energy needed to warm a substance is proportional to its mass and to the temperature rise.","tex":"E = mc\\,\\Delta\\theta","why":"c is the specific heat capacity: the joules needed to raise 1 kg by 1 K."},{"say":"Supply the energy electrically and measure it.","tex":"P t = I V t = mc\\,\\Delta\\theta \\;\\Longrightarrow\\; c = \\frac{IVt}{m\\,\\Delta\\theta}","why":"Electrical energy in equals thermal energy gained, if nothing escapes."},{"say":"During a change of state the temperature stays constant while energy is still absorbed.","tex":"E = mL","why":"The energy goes into separating the particles (potential energy), not into speeding them up. L is the specific latent heat."},{"say":"Heat losses can be eliminated by repeating at a different power for the same time and temperatures.","tex":"(P_2 - P_1)\\,t = (m_2 - m_1)\\,L","why":"The energy lost to the surroundings is the same in both runs, so it cancels in the difference."},{"say":"Thermodynamic temperature starts at absolute zero.","tex":"T / \\text{K} = \\theta / ^\\circ\\text{C} + 273.15","why":"A change of 1 K equals a change of 1 °C; only the zero differs."}],"result":"E = mc\\Delta\\theta, \\qquad E = mL, \\qquad T = \\theta + 273.15","assume":["c is taken as constant over the temperature range.","Unless losses are corrected for, a measured c comes out too high and a measured L too high as well."]},"al-thermodynamics":{"steps":[{"say":"A gas at pressure p pushes a piston of area A outwards by a small distance Δx.","tex":"W = F\\,\\Delta x = pA\\,\\Delta x","why":"Force = pressure × area, and work = force × distance."},{"say":"AΔx is the change in volume.","tex":"W = p\\,\\Delta V","why":"Work done by the gas when it expands at constant pressure. For changing pressure it is the area under the p–V graph."},{"say":"The internal energy can change by heating or by work.","tex":"\\Delta U = q + W","why":"The first law: q is energy supplied by heating and W is work done on the gas (negative when the gas expands)."},{"say":"For an ideal gas the internal energy is entirely the random kinetic energy of the molecules.","tex":"U = N \\times \\tfrac32 kT = \\tfrac32 nRT","why":"Ideal-gas molecules exert no forces on one another except in collisions, so there is no potential energy. Nk = nR."},{"say":"So for an ideal gas U depends only on temperature, and an isothermal change has q = −W.","tex":"\\Delta T = 0 \\;\\Longrightarrow\\; \\Delta U = 0 \\;\\Longrightarrow\\; q = -W","why":"All the heat supplied in an isothermal expansion leaves as work."}],"result":"\\Delta U = q + W, \\qquad W_{\\text{by gas}} = p\\Delta V, \\qquad U = \\tfrac32 nRT","assume":["Sign conventions differ: some syllabuses write ΔU = Q − W with W the work done by the gas. Always state yours.","U = (3/2)nRT is for a monatomic ideal gas; molecules that rotate or vibrate store more."]},"al-particles":{"steps":[{"say":"An alpha particle aimed straight at a nucleus stops when all its kinetic energy has become electric potential energy.","tex":"E_k = \\frac{k Q_1 Q_2}{d} \\;\\Longrightarrow\\; d_{\\min} = \\frac{k Q_1 Q_2}{E_k}","why":"Energy conservation, with k = 1/4πε₀. This gives an upper limit for the size of the nucleus, about 10⁻¹⁴ m for gold."},{"say":"Protons and neutrons are made of up and down quarks. Check the charges.","tex":"p = uud:\\ \\tfrac23 + \\tfrac23 - \\tfrac13 = +1, \\qquad n = udd:\\ \\tfrac23 - \\tfrac13 - \\tfrac13 = 0","why":"Quark charges are +⅔e for up and −⅓e for down."},{"say":"In β⁻ decay a neutron becomes a proton, so one down quark has become an up quark.","tex":"d \\rightarrow u + e^- + \\bar\\nu_e","why":"udd → uud changes one quark only. This is the weak interaction."},{"say":"Check the conservation laws.","tex":"\\text{charge: } -\\tfrac13 = \\tfrac23 - 1 + 0, \\qquad \\text{lepton number: } 0 = 0 + 1 - 1","why":"The antineutrino is needed to balance lepton number, and to explain why the electrons emerge with a range of energies."},{"say":"β⁺ decay is the mirror process.","tex":"u \\rightarrow d + e^+ + \\nu_e","why":"A proton in a nucleus becomes a neutron, emitting a positron and a neutrino."}],"result":"d_{\\min} = \\frac{kQ_1Q_2}{E_k}; \\qquad d \\rightarrow u + e^- + \\bar\\nu_e","assume":["d_{min} assumes a head-on approach and only the electric force; once the alpha is energetic enough to feel the strong force, the Rutherford formula fails, which is how nuclear radii were first measured.","A free proton cannot β⁺ decay (it is lighter than the neutron); the energy must come from the nucleus."]},"al-photons":{"steps":[{"say":"Light of frequency f arrives in quanta.","tex":"E = hf = \\frac{hc}{\\lambda}","why":"Planck’s constant h = 6.63 × 10⁻³⁴ J s. Using c = fλ."},{"say":"A convenient energy unit is the work done moving one electron through one volt.","tex":"1\\ \\text{eV} = 1.60\\times10^{-19}\\ \\text{C} \\times 1\\ \\text{V} = 1.60\\times10^{-19}\\ \\text{J}","why":"W = QV. Visible photons carry 1.6 to 3.3 eV."},{"say":"De Broglie proposed that every particle has a wavelength set by its momentum.","tex":"\\lambda = \\frac{h}{p}","why":"Confirmed when electrons were diffracted by crystals, giving rings like X-rays."},{"say":"An electron accelerated from rest through a p.d. V gains kinetic energy eV.","tex":"eV = \\frac{p^2}{2m} \\;\\Longrightarrow\\; p = \\sqrt{2meV}","why":"½mv² written in terms of p = mv."},{"say":"So its wavelength is:","tex":"\\lambda = \\frac{h}{\\sqrt{2meV}}","why":"About 0.1 nm for a few hundred volts: comparable with atomic spacings, which is why crystals diffract electrons."}],"result":"E = hf, \\qquad \\lambda = \\frac{h}{p} = \\frac{h}{\\sqrt{2meV}}","assume":["The last formula is non-relativistic: fine below a few kilovolts, increasingly wrong above about 50 kV.","Wave and particle descriptions are not alternatives to choose between: diffraction patterns build up from individual, localised arrivals."]},"al-spectra":{"steps":[{"say":"An atom can only have certain energies. When an electron drops from a higher level to a lower one, a photon carries away the difference.","tex":"hf = E_1 - E_2","why":"Energy conservation for one transition."},{"say":"So each transition gives one wavelength.","tex":"\\lambda = \\frac{hc}{E_1 - E_2}","why":"Using c = fλ. A line spectrum is the fingerprint of the set of levels."},{"say":"A shortcut in convenient units.","tex":"\\lambda\\,(\\text{nm}) \\approx \\frac{1240}{\\Delta E\\,(\\text{eV})}","why":"hc = 1.99 × 10⁻²⁵ J m = 1240 eV nm."},{"say":"For hydrogen the levels follow a simple pattern.","tex":"E_n = -\\frac{13.6\\ \\text{eV}}{n^2}","why":"Negative because the electron is bound: zero is defined as the electron just free."},{"say":"An atom excited to level n can produce a line for every pair of levels at or below n.","tex":"N_{\\text{lines}} = \\binom{n}{2} = \\frac{n(n-1)}{2}","why":"Each pair of levels gives one possible downward transition."}],"result":"hf = E_1 - E_2, \\qquad E_n = -\\frac{13.6\\ \\text{eV}}{n^2}\\ (\\text{hydrogen})","assume":["−13.6/n² is for hydrogen only; other atoms have more complicated levels because their electrons repel one another.","Absorption lines appear at the same wavelengths, because the same pairs of levels are involved."]},"al-decay":{"steps":[{"say":"Each nucleus has the same fixed probability λ of decaying in each second, regardless of its age.","tex":"\\Delta N = -\\lambda N\\,\\Delta t","why":"With N nuclei, on average λNΔt of them decay in a short time Δt. The minus sign shows N falls."},{"say":"The activity is the number of decays per second.","tex":"A = -\\frac{\\Delta N}{\\Delta t} = \\lambda N","why":"Activity is proportional to the number of undecayed nuclei."},{"say":"In the limit this is a differential equation whose solution is an exponential.","tex":"\\frac{dN}{dt} = -\\lambda N \\;\\Longrightarrow\\; N = N_0 e^{-\\lambda t}","why":"The exponential is the function whose rate of change is proportional to itself. A and the count rate follow the same law."},{"say":"The half-life is the time for N to halve.","tex":"\\tfrac12 = e^{-\\lambda t_{1/2}} \\;\\Longrightarrow\\; t_{1/2} = \\frac{\\ln 2}{\\lambda}","why":"Take natural logs of both sides."},{"say":"A straight-line test.","tex":"\\ln A = \\ln A_0 - \\lambda t","why":"Plot ln A against t: the gradient is −λ."}],"result":"A = \\lambda N, \\qquad N = N_0e^{-\\lambda t}, \\qquad t_{1/2} = \\frac{\\ln 2}{\\lambda}","assume":["Statistical law: it describes averages over many nuclei. A small sample fluctuates noticeably about the curve.","λ is unaffected by temperature, pressure or chemical state (to very high accuracy)."]},"al-medical":{"steps":[{"say":"How strongly ultrasound reflects at a boundary depends on the acoustic impedance of the two tissues.","tex":"Z = \\rho c","why":"Density × speed of sound: a measure of how hard the medium is to set vibrating."},{"say":"At a boundary the pressure and the particle velocity must match on both sides. That fixes the reflected fraction of the intensity.","tex":"\\frac{I_R}{I_0} = \\left(\\frac{Z_2 - Z_1}{Z_2 + Z_1}\\right)^2","why":"The reflected amplitude is proportional to the mismatch in Z, and intensity goes as amplitude squared. Air to skin reflects more than 99%, hence the coupling gel."},{"say":"In an X-ray tube an electron accelerated through V can give all its energy to one photon.","tex":"eV = hf_{\\max} = \\frac{hc}{\\lambda_{\\min}} \\;\\Longrightarrow\\; \\lambda_{\\min} = \\frac{hc}{eV}","why":"The spectrum has a sharp short-wavelength cut-off set by the tube voltage."},{"say":"Each thin layer of tissue removes the same fraction of the beam.","tex":"\\frac{dI}{dx} = -\\mu I \\;\\Longrightarrow\\; I = I_0 e^{-\\mu x}","why":"The same mathematics as radioactive decay. The half-value thickness is ln 2/μ."},{"say":"In PET a positron annihilates with an electron, and their rest energy appears as two photons.","tex":"2 m_e c^2 = 2 E_\\gamma \\;\\Longrightarrow\\; E_\\gamma = 0.511\\ \\text{MeV}","why":"Momentum conservation sends the two photons in opposite directions, so the line joining the two detections passes through the source."}],"result":"\\frac{I_R}{I_0} = \\left(\\frac{Z_2 - Z_1}{Z_2 + Z_1}\\right)^2, \\qquad I = I_0e^{-\\mu x}, \\qquad \\lambda_{\\min} = \\frac{hc}{eV}","assume":["The reflection formula is for normal incidence on a flat boundary.","μ depends on photon energy and on the material, so a real X-ray beam hardens as it passes through tissue."]},"al-astro":{"steps":[{"say":"A star of luminosity L radiates equally in all directions, so at distance d its power crosses a sphere.","tex":"F = \\frac{L}{4\\pi d^2}","why":"F is the radiant flux measured on Earth, in W m⁻²."},{"say":"If the luminosity is known independently (a standard candle), the flux gives the distance.","tex":"d = \\sqrt{\\frac{L}{4\\pi F}}","why":"Rearranged inverse-square law. Type Ia supernovae and Cepheid variables are used this way."},{"say":"The peak wavelength of a hot body’s spectrum gives its surface temperature.","tex":"\\lambda_{\\max} T = 2.9\\times10^{-3}\\ \\text{m K}","why":"Wien’s displacement law: hotter stars are bluer."},{"say":"Each square metre of a black body radiates σT⁴, and a star is a sphere of radius r.","tex":"L = 4\\pi r^2 \\sigma T^4","why":"Stefan–Boltzmann law × surface area."},{"say":"So flux, colour and distance together give the star’s radius.","tex":"r = \\sqrt{\\frac{L}{4\\pi\\sigma T^4}} = \\frac{d}{T^2}\\sqrt{\\frac{F}{\\sigma}}","why":"Substitute L = 4πd²F. No telescope resolves most stars; their sizes are found this way."}],"result":"F = \\frac{L}{4\\pi d^2}, \\qquad \\lambda_{\\max}T = 2.9\\times10^{-3}\\ \\text{m K}, \\qquad L = 4\\pi r^2\\sigma T^4","assume":["Assumes no dust absorbing light on the way and that the star radiates as a black body.","Standard candles are only as good as their calibration, which is one source of the present disagreement over the Hubble constant."]},"al-cosmology":{"steps":[{"say":"Light from a receding galaxy is stretched. For speeds much less than c the fractional shift equals v/c.","tex":"z = \\frac{\\Delta\\lambda}{\\lambda} \\approx \\frac{v}{c}","why":"The Doppler result for light at low speed."},{"say":"Hubble found that recession speed is proportional to distance.","tex":"v = H_0 d","why":"H₀ ≈ 70 km s⁻¹ Mpc⁻¹: every megaparsec of distance adds about 70 km/s."},{"say":"If every galaxy has always moved at its present speed, the time since they were all together is the same for all of them.","tex":"t_0 = \\frac{d}{v} = \\frac{1}{H_0}","why":"d cancels: a galaxy twice as far is moving twice as fast, so it set out at the same time."},{"say":"Convert H₀ to SI units.","tex":"H_0 = \\frac{70\\times10^{3}\\ \\text{m s}^{-1}}{3.09\\times10^{22}\\ \\text{m}} = 2.3\\times10^{-18}\\ \\text{s}^{-1}","why":"1 Mpc = 3.09 × 10²² m."},{"say":"So the age of the universe is roughly:","tex":"t_0 \\approx \\frac{1}{2.3\\times10^{-18}\\ \\text{s}^{-1}} = 4.4\\times10^{17}\\ \\text{s} \\approx 14\\ \\text{billion years}","why":"Divide by 3.16 × 10⁷ s per year."}],"result":"z \\approx \\frac{v}{c}, \\qquad v = H_0 d, \\qquad t_0 \\approx \\frac{1}{H_0}","assume":["The expansion rate has not been constant: it slowed under gravity, then began to speed up. By coincidence the corrections nearly cancel, and the accepted age is 13.8 billion years.","Cosmological redshift is really the stretching of space itself: 1 + z = a_{now}/a_{then}. The Doppler picture works only for nearby galaxies."]}});
})(window.WL);
